#!/usr/bin/env python3
import sys,csv,argparse,re,os
import ops_sort

def read_csv(path, delim):
    f=open(path,encoding='utf-8',newline='') if path and path!='-' else sys.stdin
    return f, list(csv.reader(f,delimiter=delim))

def write(rows, delim=','):
    w=csv.writer(sys.stdout,delimiter=delim,lineterminator='\n')
    w.writerows(rows)

def split_selection(s):
    return [x.strip().strip('"') for x in s.split(',') if x.strip()]

def col_index(token, header, n):
    if token.lstrip('-').isdigit():
        i=int(token); i=i if i>=0 else n+i
        if 0<=i<n:return i
    if token in header:
        return header.index(token)
    m=re.fullmatch(r'(.+)\[(-?\d+)\]',token)
    if m:
        inds=[i for i,x in enumerate(header) if x==m.group(1)]
        j=int(m.group(2)); j=j if j>=0 else len(inds)+j
        if 0<=j<len(inds):return inds[j]
    raise ValueError('Unknown column: '+token)

def selection(s, header, n):
    out=[]
    for tok in split_selection(s):
        if tok=='*': out.extend(range(n)); continue
        if '*' in tok:
            if tok.startswith('*'): out.extend(i for i,x in enumerate(header) if x.endswith(tok[1:]))
            elif tok.endswith('*'): out.extend(i for i,x in enumerate(header) if x.startswith(tok[:-1]))
            continue
        if ':' in tok:
            a,b=tok.split(':',1)
            lo=col_index(a,header,n) if a else 0
            hi=col_index(b,header,n) if b else n-1
            step=1 if hi>=lo else -1
            out.extend(range(lo,hi+step,step));continue
        out.append(col_index(tok,header,n))
    return out

def main():
    args=sys.argv[1:]
    if not args or args[0] in ('-h','--help'):
        print('Usage: xan [options] <command> [<args>...]');return
    if args[0]=='--version': print('0.57.1');return
    delim=','; nohead=False; output=None
    i=0
    while i<len(args) and args[i] in ('-n','--no-headers','-d','--delimiter','-o','--output'):
        a=args[i]
        if a in ('-n','--no-headers'): nohead=True;i+=1
        else:
            if i+1>=len(args): raise ValueError('missing value for '+a)
            if a in ('-d','--delimiter'):delim=args[i+1]
            else:output=args[i+1]
            i+=2
    cmd=args[i]; rest=args[i+1:]
    if cmd in ('sort','range'):
        return ops_sort.run(cmd, rest)
    if cmd in ('flatten','f'):
        flatten(rest); return
    opts={}; positional=[]; j=0
    valued={'-s':'select','--select':'select','-c':'column','--column-name':'column','-S':'start','--start':'start','-l':'limit','--limit':'limit'}
    while j<len(rest):
        a=rest[j]
        if a in ('-n','--no-headers'):nohead=True
        elif a in ('-d','--delimiter') and j+1<len(rest):delim=rest[j+1];j+=1
        elif a in ('-o','--output') and j+1<len(rest):output=rest[j+1];j+=1
        elif a in valued and j+1<len(rest):opts[valued[a]]=rest[j+1];j+=1
        elif a.startswith('-') and a not in ('--',): opts[a]=True
        else: positional.append(a)
        j+=1
    if cmd in ('select','drop','rename','enum','behead','guillotine'):
        if cmd=='rename' and not positional and not any(k in opts for k in ('-p','--prefix','-x','--suffix')):pass
        arg=positional[0] if positional and cmd not in ('enum','behead','guillotine') else None
        path=positional[-1] if len(positional)>1 or (positional and cmd in ('enum','behead','guillotine')) else None
        f,rows=read_csv(path,delim)
        if f is not sys.stdin:f.close()
        if not rows:return
        head=[] if nohead else rows[0]
        data=rows if nohead else rows[1:]
        if cmd in ('select','drop'):
            ids=selection(arg or '',head,len(rows[0]))
            if cmd=='drop':ids=[x for x in range(len(rows[0])) if x not in ids]
            result=[[r[k] for k in ids] for r in rows]
        elif cmd=='rename':
            names=next(csv.reader([arg or ''],delimiter=delim))
            base=[str(i) for i in range(len(rows[0]))] if nohead else head[:]
            base=(names+base[len(names):])
            if nohead:result=[base]+rows
            else:result=[base]+data
        elif cmd=='enum':
            start=int(opts.get('start',0));name=opts.get('column','index')
            result=([[name]+rows[0]] if not nohead else [])
            result += [[str(start+k)]+r for k,r in enumerate(data)]
        else: result=rows[1:]
        if output:
            with open(output,'w',encoding='utf-8',newline='') as of:csv.writer(of,delimiter=delim,lineterminator='\n').writerows(result)
        else:write(result,delim)
        return
    raise ValueError('Unknown command: '+cmd)

# Basic flattened row display command.
def flatten(args):
    import argparse
    p=argparse.ArgumentParser(prog='xan flatten')
    p.add_argument('-n','--no-headers',action='store_true'); p.add_argument('-d','--delimiter',default=','); p.add_argument('-o','--output'); p.add_argument('-l','--limit',type=int)
    p.add_argument('input',nargs='?'); ns,_=p.parse_known_args(args)
    f,rows=read_csv(ns.input,ns.delimiter)
    if f is not sys.stdin:f.close()
    if ns.no_headers: heads=[str(i) for i in range(max(map(len,rows),default=0))]; data=rows
    else: heads=rows[0] if rows else []; data=rows[1:]
    for i,row in enumerate(data[:ns.limit] if ns.limit is not None else data):
        if i: print()
        print(f'Row n°{i}\n'+'─'*80)
        width=max([len(x) for x in heads]+[0])
        for j,v in enumerate(row): print(f'{(heads[j] if j<len(heads) else str(j)):<{width}} {v if v else "<empty>"}')

if __name__=='__main__':
    try: main()
    except Exception as e:
        print('error: '+str(e),file=sys.stderr);sys.exit(1)

